(() => {
  const css=document.createElement('style');css.textContent=`.advanced-filters{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:0 0 22px}.advanced-filters select,.availability input{font:inherit;padding:10px;border:1px solid var(--line);border-radius:9px;background:var(--white);color:var(--ink)}.availability{margin:18px 0;padding:16px;background:var(--sand);border-radius:12px}.availability-grid{display:grid;grid-template-columns:1fr 1fr auto;gap:8px}.availability-result{margin:10px 0 0;font-weight:700}@media(max-width:700px){.advanced-filters,.availability-grid{grid-template-columns:1fr}}`;document.head.append(css);
  const grid=document.getElementById('cabinGrid');if(!grid)return;const bar=document.createElement('div');bar.className='advanced-filters';bar.innerHTML='<select id="capFilter"><option value="">Capacidad</option><option value="2">Hasta 3 personas</option><option value="4">4 a 5 personas</option><option value="6">6 o más personas</option></select><select id="bedFilter"><option value="">Dormitorios</option><option value="1">1 dormitorio</option><option value="2">2+ dormitorios</option><option value="3">3+ dormitorios</option></select><select id="poolFilter"><option value="">Piscina</option><option value="propia">Piscina propia</option><option value="compartida">Piscina compartida</option></select><select id="priceFilter"><option value="">Precio desde</option><option value="90000">Hasta $90.000</option><option value="120000">Hasta $120.000</option><option value="999999">Cualquier precio</option></select>';grid.before(bar);
  const apply=()=>{const cap=+document.getElementById('capFilter').value,bed=+document.getElementById('bedFilter').value,pool=document.getElementById('poolFilter').value,price=+document.getElementById('priceFilter').value;grid.querySelectorAll('.cabin').forEach(card=>{const text=card.textContent,people=+(text.match(/Hasta (\d+)/)||[,0])[1],rooms=+(text.match(/· (\d+) dormitorio/)||[,0])[1],own=text.includes('Piscina propia'),amount=+(text.match(/\$([\d.]+)/)||['','$0'])[1].replaceAll('.','');const ok=(!cap||(cap===2?people<=3:cap===4?people>=4&&people<=5:people>=6))&&(!bed||rooms>=bed)&&(!pool||(pool==='propia'?own:!own))&&(!price||amount<=price);card.style.display=ok?'':'none'})};bar.querySelectorAll('select').forEach(x=>x.onchange=apply);
  document.addEventListener('click',e=>{const b=e.target.closest('[data-cabin]');if(!b)return;setTimeout(()=>{const content=document.getElementById('modalContent');if(!content||content.querySelector('.availability'))return;const card=b.closest('.cabin'),name=card.querySelector('h3')?.textContent||'cabaña';const box=document.createElement('div');box.className='availability';box.innerHTML='<b>Consulta disponibilidad de '+name+'</b><div class="availability-grid"><input type="date" class="from"><input type="date" class="to"><button class="btn btn-primary check">Ver disponibilidad</button></div><div class="availability-result"></div>';box.querySelector('.check').onclick=async()=>{const from=box.querySelector('.from').value,to=box.querySelector('.to').value,result=box.querySelector('.availability-result');if(!from||!to)return result.textContent='Selecciona ingreso y salida.';const r=await fetch('/api/bookings?resource='+encodeURIComponent(name)+'&from='+from+'&to='+to);const d=await r.json();result.textContent=d.available?'✓ Disponible para consultar reserva':'No disponible para esas fechas. Prueba otras fechas.'};content.append(box)},0)},true);
})();
